import os,re,sys
sys.argv=['x']
src=open('/tmp/ajc_audit.py').read()
ns={}
exec("import re,os\n"+src[src.index('IDENT = set'):src.index('def modname')], ns)
strip=ns['strip_comments']; W=ns['WORD_SORRY']
ROOT="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
EX="AlgebraicJacobian.Picard.DivisorFamilyAffFrameCover"
mods={}
for dp,dn,fn in os.walk(os.path.join(ROOT,"AlgebraicJacobian")):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f); mods[os.path.relpath(p,ROOT)[:-5].replace('/','.')]=p
mods["AlgebraicJacobian"]=os.path.join(ROOT,"AlgebraicJacobian.lean")
IMP=re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)\s*$',re.M)
imports={m:[t for t in IMP.findall(strip(open(p,encoding='utf-8').read()))] for m,p in mods.items()}
junk={t for ts in imports.values() for t in ts if t.startswith("AlgebraicJacobian") and t not in mods}
print("in-project import targets with no file:",junk or "NONE")
nonmathlib={t for ts in imports.values() for t in ts if not t.startswith(("Mathlib","AlgebraicJacobian"))}
print("non-Mathlib non-project imports:",nonmathlib or "NONE")
def closure(excl):
    seen={"AlgebraicJacobian"}; dq=["AlgebraicJacobian"]
    while dq:
        c=dq.pop()
        for t in imports.get(c,[]):
            if t in mods and t not in excl and t not in seen:
                seen.add(t); dq.append(t)
    universe=set(mods)-excl
    return len(universe), len(seen), sorted(universe-seen)
for label,excl in [("ALL FILES ON DISK",set()),("EXCLUDING FrameCover",{EX})]:
    tot,reach,un=closure(excl)
    sor=sum(len(W.findall(strip(open(mods[m],encoding='utf-8').read()))) for m in mods if m not in excl)
    print(f"\n{label}: total(with root)={tot} total(without root)={tot-1} reachable={reach} UNROOTED={len(un)} code_sorries={sor}")
